import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Weapons and Damage Types","description":"","frontmatter":{},"headers":[],"relativePath":"guide/combat/weapons-and-damage.md","filePath":"guide/combat/weapons-and-damage.md"}'),i={name:"guide/combat/weapons-and-damage.md"};function s(r,e,d,c,l,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="weapons-and-damage-types" tabindex="-1">Weapons and Damage Types <a class="header-anchor" href="#weapons-and-damage-types" aria-label="Permalink to &quot;Weapons and Damage Types&quot;">​</a></h1><ul><li><strong>Design status:</strong> Proposed family-specific behavior; Accepted health/trauma distinction.</li><li><strong>Implementation:</strong> No new weapon-family effects implemented in this batch.</li><li><strong>Availability:</strong> no new live behavior established here; current configuration not inspected.</li><li><strong>Verification:</strong> documentation reviewed 2026-10-08; no new playtest. Existing evidence is scoped in <a href="/Syrolands-Public/game-design/combat/status-and-open-questions.html">combat status</a>.</li></ul><h2 id="choose-a-way-to-fight" tabindex="-1">Choose a way to fight <a class="header-anchor" href="#choose-a-way-to-fight" aria-label="Permalink to &quot;Choose a way to fight&quot;">​</a></h2><p>The direction is for weapons to pose different tactical problems. A sword can support cuts and thrusts; a spear emphasizes reach and piercing; a warhammer emphasizes impact; an axe combines cutting with structural force. These identities are proposals, not guarantees of penetration, fractures or armor destruction.</p><p>A well-crafted weapon should perform its own design more consistently. It should not simply win every matchup through a larger damage number. Quality, condition, protection and the opportunity you choose should matter together.</p><h2 id="read-the-encounter" tabindex="-1">Read the encounter <a class="header-anchor" href="#read-the-encounter" aria-label="Permalink to &quot;Read the encounter&quot;">​</a></h2><p>Character skill supplies capability, knowledge informs your choices, and your timing and positioning affect execution. The proposed differences still need evaluation against shields, armor, stamina and injuries. Ranged aimed shots and multi-region cleave are not established by the current melee experiment.</p><p><a href="/Syrolands-Public/game-design/combat/weapons-and-damage.html">Full weapon specification</a> · <a href="/Syrolands-Public/guide/items/item-quality.html">Item Quality</a> · <a href="/Syrolands-Public/guide/combat/armor-and-protection.html">Armor and Protection</a>.</p><p><a href="/Syrolands-Public/guide/combat/overview.html">Back to Combat overview</a></p>',9)])])}const u=a(i,[["render",s]]);export{h as __pageData,u as default};
